<template><section class="card"><h1>Welcome back</h1><form @submit.prevent="login"><input v-model="email" type="email" placeholder="Email" required/><input v-model="password" type="password" placeholder="Password" minlength="8" required/><button>Sign in</button><p v-if="error">{{error}}</p></form></section></template><script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';const email=ref('');const password=ref('');const error=ref('');const router=useRouter();function login(){if(!email.value||password.value.length<8){error.value='Please enter valid credentials';return}localStorage.setItem('accessToken','demo-token');router.push('/')}</script><style>.card{background:white;padding:32px;border-radius:14px;max-width:420px;margin:auto}input,button{display:block;width:100%;box-sizing:border-box;padding:12px;margin:12px 0}button{cursor:pointer}</style>